    d={}
    for s in samples:
        d.setdefault(s['variant'],[]).append(s)
    return d

def budget6_cycle(samples):
    # one sample from each variant 0-4, then second sample from variant0
    d = by_variant(samples)
    order = [0,1,2,3,4,0]
    idx = {v:0 for v in range(5)}
